{
    "id": "vuln-notesnook-e87f5e5f",
    "message": "Potential XSS vulnerability in embed component where user-provided 'src' parameter is directly inserted into HTML without proper sanitization. This can allow attackers to inject malicious scripts via the href attribute. The fix involves creating a DOM element and using its outerHTML property to properly escape the URL. Ensure all external URLs are sanitized before insertion into HTML.",
    "severity": "ERROR",
    "languages": ["typescript"],
    "metadata": {
        "category": "security",
        "cwe": "79",
        "owasp": "OWASP Top 10:2021 - A03:2021 - Injection"
    },
    "pattern_either": [
        "const $VAR = \"<p lang=\\\"en\\\" dir=\\\"ltr\\\"><a href=\\\"${...}?ref_src=twsrc%5Etfw\"></a></blockquote>\"",
        "const $VAR = `<p lang=\"en\" dir=\"ltr\"><a href=\"${...}?ref_src=twsrc%5Etfw\"></a></blockquote>`"
    ],
    "pattern_not": [
        "const anchor = document.createElement(\"a\");",
        "anchor.href = `${src}?ref_src=twsrc%5Etfw`;",
        "anchor.outerHTML"
    ]
}

